{
  "schema": "acpx.flow-definition-snapshot.v1",
  "name": "golden-acp",
  "run": {
    "hasTitle": true
  },
  "startAt": "plan",
  "nodes": {
    "plan": {
      "nodeType": "acp",
      "heartbeatMs": 0,
      "profile": "mock",
      "session": {
        "isolated": true
      },
      "cwd": {
        "mode": "default"
      },
      "hasPrompt": true,
      "hasParse": true
    },
    "blocks": {
      "nodeType": "acp",
      "heartbeatMs": 0,
      "statusDetail": "Sending blocks",
      "profile": "mock",
      "session": {
        "isolated": true
      },
      "cwd": {
        "mode": "dynamic"
      },
      "hasPrompt": true,
      "hasParse": false
    },
    "risky": {
      "nodeType": "acp",
      "heartbeatMs": 0,
      "profile": "mock",
      "session": {
        "isolated": true
      },
      "cwd": {
        "mode": "default"
      },
      "hasPrompt": true,
      "hasParse": false
    },
    "recover": {
      "nodeType": "compute",
      "heartbeatMs": 0,
      "hasRun": true
    },
    "review": {
      "nodeType": "checkpoint",
      "summary": "Check the replies",
      "hasRun": false
    }
  },
  "edges": [
    {
      "from": "plan",
      "to": "blocks"
    },
    {
      "from": "blocks",
      "to": "risky"
    },
    {
      "from": "risky",
      "switch": {
        "on": "$result.outcome",
        "cases": {
          "failed": "recover",
          "ok": "recover"
        }
      }
    },
    {
      "from": "recover",
      "to": "review"
    }
  ]
}

